# User Service Implementation

```python
class UserService:
    def __init__(self):
        self.db = Database()
        self.cache = Redis()
        self.email = EmailService()
        self.logger = Logger()

    def create_user(self, data):
        # Validate
        if not data.get('email'):
            return {'error': 'Email required'}
        if not data.get('password'):
            return {'error': 'Password required'}
        if len(data['password']) < 8:
            return {'error': 'Password too short'}

        # Check existing
        existing = self.db.query("SELECT * FROM users WHERE email = '" + data['email'] + "'")
        if existing:
            return {'error': 'Email exists'}

        # Create
        user = self.db.query(f"INSERT INTO users (email, password) VALUES ('{data['email']}', '{data['password']}') RETURNING *")

        # Cache
        self.cache.set(f"user:{user['id']}", user)

        # Email
        self.email.send(data['email'], 'Welcome!', 'Thanks for signing up')

        self.logger.info('User created: ' + data['email'])
        return user
```

